[CmdletBinding()] param([string]$Url='http://localhost/greenportal',[Parameter(Mandatory)][string]$Empresa,[Parameter(Mandatory)][string]$Usuario,[Parameter(Mandatory)][string]$Senha,[switch]$Headless,[string]$Saida='tests/evidencias-historico-situacao')
$ErrorActionPreference='Stop'; $repo=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path; Push-Location $repo; try { node --check scripts/teste-visual-historico-situacao-v2.js; if($LASTEXITCODE -ne 0){throw 'Sintaxe JavaScript inválida.'}; $a=@('scripts/teste-visual-historico-situacao-v2.js','--url',$Url,'--empresa',$Empresa,'--usuario',$Usuario,'--senha',$Senha,'--saida',$Saida); if(-not $Headless){$a+='--visivel'}; & node @a; if($LASTEXITCODE -ne 0){throw "Teste visual terminou com código $LASTEXITCODE."} } finally { Pop-Location }
